import * as T from 'three';
import {RoundedBoxGeometry} from '../vendor/RoundedBoxGeometry.js';
export {T};
export function rng(seed=9){return()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};}
export function material(color,metalness=.3,roughness=.55){return new T.MeshStandardMaterial({color,metalness,roughness});}
export function glow(color,power=1.5){return new T.MeshStandardMaterial({color,emissive:color,emissiveIntensity:power,roughness:.3,toneMapped:false});}
export function surface(kind,color,metalness=.1){const c=document.createElement('canvas');c.width=c.height=512;const ctx=c.getContext('2d'),r=rng(345);ctx.fillStyle='#bfbfbf';ctx.fillRect(0,0,512,512);for(let i=0;i<14000;i++){const v=120+Math.floor(r()*100);ctx.fillStyle=`rgba(${v},${v},${v},${kind==='paper'?.08:.2})`;ctx.fillRect(r()*512,r()*512,r()*2+1,r()*2+1);}if(kind==='wood'){for(let i=0;i<220;i++){ctx.strokeStyle=`rgba(55,40,30,${r()*.17})`;ctx.lineWidth=r()*2;ctx.beginPath();const x=r()*512;ctx.moveTo(x,0);ctx.bezierCurveTo(x+14,130,x-9,380,x+r()*10,512);ctx.stroke();}}else if(kind==='tatami'){for(let y=0;y<512;y+=3){ctx.fillStyle=y%6?'#b4b4b4':'#cbcbcb';ctx.fillRect(0,y,512,1);}}else if(kind==='metal'){for(let i=0;i<180;i++){ctx.strokeStyle=`rgba(245,245,245,${r()*.14})`;ctx.beginPath();let y=r()*512;ctx.moveTo(r()*512,y);ctx.lineTo(r()*512,y);ctx.stroke();}}const texture=new T.CanvasTexture(c);texture.wrapS=texture.wrapT=T.RepeatWrapping;texture.colorSpace=T.SRGBColorSpace;texture.anisotropy=4;const mat=material(color,metalness,kind==='metal'?.38:.78);mat.map=texture;mat.bumpMap=texture;mat.bumpScale=kind==='wood'?.035:.012;return mat;}

export function batch(root){const sets=new Map(),dummy=new T.Object3D(),up=new T.Vector3(0,1,0);let parent=new T.Matrix4();function add(type,mat,x,y,z,w,h,d,rx=0,ry=0,rz=0){dummy.position.set(x,y,z);dummy.rotation.set(rx,ry,rz);dummy.scale.set(w,h,d);dummy.updateMatrix();if(!sets.has(mat))sets.set(mat,new Map());const byType=sets.get(mat);if(!byType.has(type))byType.set(type,[]);byType.get(type).push(parent.clone().multiply(dummy.matrix));}
 return {box:(...a)=>add('box',...a),round:(...a)=>add('round',...a),cylinder:(...a)=>add('cylinder',...a),sphere:(...a)=>add('sphere',...a),
 beam(mat,a,b,w=.12,round=false){const p=new T.Vector3(...a),q=new T.Vector3(...b),mid=p.clone().add(q).multiplyScalar(.5),rot=new T.Euler().setFromQuaternion(new T.Quaternion().setFromUnitVectors(up,q.clone().sub(p).normalize()));add(round?'cylinder':'box',mat,mid.x,mid.y,mid.z,w,p.distanceTo(q),w,rot.x,rot.y,rot.z);},
 transform(x,y,z,ry=0,rz=0,s=1){parent.compose(new T.Vector3(x,y,z),new T.Quaternion().setFromEuler(new T.Euler(0,ry,rz)),new T.Vector3(s,s,s));},identity(){parent.identity();},
 finish(){let count=0;for(const [mat,types]of sets)for(const[type,matrices]of types){const g=type==='round'?new RoundedBoxGeometry(1,1,1,1,.055):type==='cylinder'?new T.CylinderGeometry(.5,.5,1,10):type==='sphere'?new T.SphereGeometry(.5,10,7):new T.BoxGeometry(1,1,1);const m=new T.InstancedMesh(g,mat,matrices.length);matrices.forEach((v,i)=>m.setMatrixAt(i,v));m.computeBoundingSphere();m.castShadow=!mat.emissiveIntensity;m.receiveShadow=true;root.add(m);count+=matrices.length;}root.userData.instances=(root.userData.instances||0)+count;return count;}
 };
}
export function mesh(root,g,m,p=[0,0,0],r=[0,0,0]){const o=new T.Mesh(g,m);o.position.set(...p);o.rotation.set(...r);o.castShadow=!!m.isMeshStandardMaterial&&!m.transparent;o.receiveShadow=true;root.add(o);return o;}
export function text(root,words,p,width,color='#d8d7c9',r=[0,0,0],height=1){const c=document.createElement('canvas');c.width=1024;c.height=128;const ctx=c.getContext('2d');ctx.fillStyle=color;ctx.font='600 76px Arial';ctx.textBaseline='middle';ctx.fillText(words,20,65);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;return mesh(root,new T.PlaneGeometry(width,height),new T.MeshBasicMaterial({map:tex,transparent:true,depthWrite:false,side:T.DoubleSide}),p,r);}
export function lighting(scene,sky='#a8bfcd',ground='#24252a',power=1.4){scene.add(new T.HemisphereLight(sky,ground,power));const key=new T.DirectionalLight('#f4e8d5',3.5);key.position.set(45,85,35);key.castShadow=true;key.shadow.mapSize.set(2048,2048);Object.assign(key.shadow.camera,{left:-110,right:110,top:110,bottom:-110,near:1,far:300});key.shadow.normalBias=.08;key.shadow.bias=-.0002;scene.add(key);const fill=new T.DirectionalLight('#8eb5d3',1.3);fill.position.set(-80,25,-90);scene.add(fill);return key;}
export function stars(scene,count=3000,radius=800,color='#c6dcff'){const r=rng(53),p=[];for(let i=0;i<count;i++){const a=r()*Math.PI*2,u=r()*2-1,s=Math.sqrt(1-u*u),d=radius*(.75+r()*.25);p.push(d*s*Math.cos(a),d*u,d*s*Math.sin(a));}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));const pts=new T.Points(g,new T.PointsMaterial({color,size:.38,transparent:true,opacity:.7,sizeAttenuation:true,depthWrite:false}));scene.add(pts);return pts;}
export function rail(b,mat,light,a,c,height=1.4){const len=new T.Vector3(...a).distanceTo(new T.Vector3(...c));for(let i=0;i<=Math.ceil(len/2);i++){const v=new T.Vector3(...a).lerp(new T.Vector3(...c),i/Math.ceil(len/2));b.cylinder(mat,v.x,v.y+height/2,v.z,.09,height,.09);b.round(mat,v.x,v.y+.05,v.z,.3,.1,.3);}for(const y of [.55,height])b.beam(mat,[a[0],a[1]+y,a[2]],[c[0],c[1]+y,c[2]],.07,true);if(light)b.beam(light,[a[0],a[1]+.12,a[2]],[c[0],c[1]+.12,c[2]],.025,true);}
export function portal(scene,b,steel,id,pos,color){const[x,y,z]=pos,l=glow(color,2);for(const s of [-1,1]){b.round(steel,x+s*2.3,y+3,z,.7,6.7,1.3);b.box(l,x+s*1.93,y+3,z+.7,.07,5.7,.03);for(let i=0;i<8;i++)b.box(steel,x+s*2.65,y+.4+i*.75,z,.35,.2,1.6);}b.round(steel,x,y+6.3,z,5.1,.65,1.4);b.round(steel,x,y+.1,z,6,.2,3);b.box(l,x,y+6.04,z+.71,3.9,.04,.025);const o=mesh(scene,new T.PlaneGeometry(3.8,5.7),new T.MeshBasicMaterial({color,side:T.DoubleSide,transparent:true,opacity:.85}),[x,y+3,z+.1]);o.userData.portal=id;text(scene,id.toUpperCase(),[x-1.7,y+6.85,z+.7],4.4,color,[0,0,0],.5);return{id,position:new T.Vector3(x,y+7.2,z),object:o};}
